2	
3	import { For, Show, createMemo, createSignal, onCleanup, onMount } from 'solid-js';
4	import { useKeyboard, useRenderer, useTerminalDimensions } from '@opentui/solid';
5	import type { KeyEvent } from '@opentui/core';
6	import type { AppPaths } from './paths.ts';
7	import { discoverAll } from './discovery.ts';
8	import {
9	  deleteSkills,
10	  findForkCollision,
11	  findMoveCollisions,
12	  forkSkill,
13	  moveSkills,
14	  normalizeForkName,
15	} from './operations.ts';
16	import {
17	  findInstallCollision,
18	  installSearchResult,
19	  loadInstallPreview,
20	  SEARCH_PAGE_SIZE,
21	  searchNeedsMore,
22	  searchSkills,
23	  type InstallPreview,
24	  type SearchSkill,
25	} from './install.ts';
26	import { checkForUpdates, updateSkills } from './updates.ts';
27	import type { AppSnapshot, OperationResult, ScopeId, SkillRecord, UpdateState } from './types.ts';
28	import { COLORS, shortenHome } from './ui/common.tsx';
29	import { SkillPane } from './ui/panes.tsx';
30	import { StatusBar } from './ui/statusbar.tsx';
31	import {
32	  ConfirmView,
33	  ForkView,
34	  ModalFrame,
35	  SearchQueryView,
36	  SearchResultsView,
37	  searchResultsCapacity,
38	  type ForkModal,
39	  type Modal,
40	  type SearchModal,
41	} from './ui/modals.tsx';
42	
43	function allSkills(snapshot: AppSnapshot | null): SkillRecord[] {
44	  return snapshot ? [...snapshot.project.skills, ...snapshot.global.skills] : [];
45	}
46	
47	function isEnter(key: KeyEvent): boolean {
48	  return key.name === 'return' || key.name === 'enter';
49	}
50	
51	function typedCharacter(key: KeyEvent): string | null {
52	  if (key.ctrl || key.meta || key.option) return null;
53	  return key.raw.length === 1 && key.raw >= ' ' && key.raw !== '\x7f' ? key.raw : null;
54	}
55	
56	function operationStatus(result: OperationResult): string {
57	  if (result.errors.length === 0) return result.message;
58	  return `${result.message}. ${result.errors[0]}`;
59	}
60	
61	export function App(props: { paths: AppPaths }) {
62	  const renderer = useRenderer();
63	  const dimensions = useTerminalDimensions();
64	  const [snapshot, setSnapshot] = createSignal<AppSnapshot | null>(null);
65	  const [activeScope, setActiveScope] = createSignal<ScopeId>('project');
66	  const [cursor, setCursor] = createSignal<Record<ScopeId, number>>({ project: 0, global: 0 });
67	  const [selected, setSelected] = createSignal(new Set<string>());
68	  const [updates, setUpdates] = createSignal<Record<string, UpdateState>>({});
69	  const [status, setStatus] = createSignal('Loading skills');
70	  const [statusTone, setStatusTone] = createSignal<'idle' | 'alert'>('idle');
71	  const [busy, setBusy] = createSignal(false);
72	  const [modal, setModal] = createSignal<Modal | null>(null);
73	  const installPreviewCache = new Map<string, InstallPreview>();
74	  let disposed = false;
75	  let checkGeneration = 0;
76	  let previewGeneration = 0;
77	  let searchGeneration = 0;
78	
79	  function announce(message: string, alert = false): void {
80	    setStatus(message);
81	    setStatusTone(alert ? 'alert' : 'idle');
82	  }
83	
84	  const scopeSnapshot = (scope: ScopeId) => snapshot()?.[scope];
85	  const scopeSkills = (scope: ScopeId) => scopeSnapshot(scope)?.skills || [];
86	  const currentSkill = createMemo(() => {
87	    const list = scopeSkills(activeScope());
88	    return list[cursor()[activeScope()]] || null;
89	  });
90	  const selectedSkills = createMemo(() => {
91	    const ids = selected();
92	    return allSkills(snapshot()).filter((skill) => ids.has(skill.id));
93	  });
94	
95	  function clampCursors(data: AppSnapshot): void {
96	    setCursor((previous) => ({
97	      project: Math.max(0, Math.min(previous.project, data.project.skills.length - 1)),
98	      global: Math.max(0, Math.min(previous.global, data.global.skills.length - 1)),
99	    }));
100	  }
101	
102	  async function runBackgroundCheck(data: AppSnapshot): Promise<void> {
103	    const generation = ++checkGeneration;
104	    const tracked = allSkills(data).filter((skill) => skill.tracked);
105	    const initial: Record<string, UpdateState> = {};
106	    for (const skill of tracked) initial[skill.id] = 'checking';
107	    setUpdates(initial);
108	    if (tracked.length === 0) return;
109	
110	    const result = await checkForUpdates(tracked);
111	    if (disposed || generation !== checkGeneration) return;
112	    setUpdates(result.states);
113	    const available = Object.values(result.states).filter((state) => state === 'available').length;
114	    if (available > 0) {
115	      announce(`${available} update${available === 1 ? '' : 's'} available`, true);
116	    } else if (result.errors.length > 0) {
117	      announce('Local skills ready. Some updates could not be checked', true);
118	    }
119	  }
120	
121	  async function refresh(check = true): Promise<void> {
122	    try {
123	      const data = await discoverAll(props.paths);
124	      if (disposed) return;
125	      setSnapshot(data);
126	      clampCursors(data);
127	      const existing = new Set(allSkills(data).map((skill) => skill.id));
128	      setSelected((previous) => new Set([...previous].filter((id) => existing.has(id))));
129	      announce(`${data.project.skills.length} project, ${data.global.skills.length} global`);
130	      if (check) void runBackgroundCheck(data);
131	    } catch (error) {
132	      announce((error as Error).message, true);
133	    }
134	  }
135	
136	  async function runOperation(
137	    label: string,
138	    action: () => Promise<OperationResult>
139	  ): Promise<void> {
140	    setModal(null);
141	    setBusy(true);
142	    announce(label);
143	    try {
144	      const result = await action();
145	      setSelected(new Set<string>());
146	      await refresh(true);
147	      announce(operationStatus(result), result.errors.length > 0);
148	    } catch (error) {
149	      announce((error as Error).message, true);
150	    } finally {
151	      setBusy(false);
152	    }
153	  }
154	
155	  function actionTargets(scope?: ScopeId): SkillRecord[] {
156	    const chosen = selectedSkills().filter((skill) => !scope || skill.scope === scope);
157	    if (chosen.length > 0) return chosen;
158	    const current = currentSkill();
159	    return current && (!scope || current.scope === scope) ? [current] : [];
160	  }
161	
162	  function openDelete(): void {
163	    const targets = actionTargets();
164	    if (targets.length === 0) {
165	      announce('No skill to delete', true);
166	      return;
167	    }
168	    setModal({
169	      type: 'confirm',
170	      title: `Delete ${targets.length} skill${targets.length === 1 ? '' : 's'}?`,
171	      lines: ['These folders will be removed:', '', ...targets.map((skill) => skill.path)],
172	      offset: 0,
173	      action: () => runOperation('Deleting skills', () => deleteSkills(props.paths, targets)),
174	    });
175	  }
176	
177	  async function startMove(): Promise<void> {
178	    const scope = activeScope();
179	    const targets = actionTargets(scope);
180	    if (targets.length === 0) {
181	      announce('No skill to move', true);
182	      return;
183	    }
184	    setBusy(true);
185	    try {
186	      const collisions = await findMoveCollisions(props.paths, targets);
187	      if (collisions.length > 0) {
188	        setModal({
189	          type: 'confirm',
190	          title: `Overwrite ${collisions.length} destination${collisions.length === 1 ? '' : 's'}?`,
191	          lines: [
192	            'Existing folders and their lock entries will be replaced:',
193	            '',
194	            ...collisions.flatMap((collision) => [
195	              collision.destination,
196	              `from ${collision.source}`,
197	            ]),
198	          ],
199	          offset: 0,
200	          action: () => runOperation('Moving skills', () => moveSkills(props.paths, targets, true)),
201	        });
202	      } else {
203	        await runOperation('Moving skills', () => moveSkills(props.paths, targets));
204	      }
205	    } finally {
206	      setBusy(false);
207	    }
208	  }
209	
210	  function openFork(): void {
211	    const selectedNow = selectedSkills();
212	    if (selectedNow.length > 1) {
213	      announce('Fork accepts one skill', true);
214	      return;
215	    }
216	    const skill = selectedNow[0] || currentSkill();
217	    if (!skill) {
218	      announce('No skill to fork', true);
219	      return;
220	    }
221	    setModal({ type: 'fork', skill, value: `${skill.folderName}-fork` });
222	  }
223	
224	  async function submitFork(forkModal: ForkModal): Promise<void> {
225	    const name = normalizeForkName(forkModal.value);
226	    if (!name) {
227	      announce('Fork name is empty', true);
228	      return;
229	    }
230	    setBusy(true);
231	    try {
232	      const collision = await findForkCollision(props.paths, forkModal.skill, name);
233	      if (collision) {
234	        setModal({
235	          type: 'confirm',
236	          title: `Overwrite ${name}?`,
237	          lines: [
238	            'The existing fork destination and its lock entry will be replaced:',
239	            '',
240	            collision.destination,
241	          ],
242	          offset: 0,
243	          action: () =>
244	            runOperation('Forking skill', () =>
245	              forkSkill(props.paths, forkModal.skill, name, true)
246	            ),
247	        });
248	      } else {
249	        await runOperation('Forking skill', () => forkSkill(props.paths, forkModal.skill, name));
250	      }
251	    } finally {
252	      setBusy(false);
253	    }
254	  }
255	
256	  function searchStatus(count: number, hasMore: boolean, loadingMore = false): string {
257	    if (count === 0) return 'No results, or skills.sh could not be reached';
258	    const noun = `${count} result${count === 1 ? '' : 's'}`;
259	    if (loadingMore) return `${noun} · loading more`;
260	    return hasMore ? `${noun} · more available` : noun;
261	  }
262	
263	  function openSearch(scope: ScopeId): void {
264	    previewGeneration++;
265	    searchGeneration++;
266	    setModal({
267	      type: 'search',
268	      scope,
269	      phase: 'query',
270	      query: '',
271	      results: [],
272	      index: 0,
273	      loading: false,
274	      loadingMore: false,
275	      hasMore: false,
276	      message: 'Type at least two characters, then press Enter',
277	      preview: '',
278	      previewFile: '',
279	      previewState: 'idle',
280	      previewOffset: 0,
281	    });
282	  }
283	
284	  function previewKey(result: SearchSkill): string {
285	    return `${result.source}\0${result.name}`;
286	  }
287	
288	  async function selectSearchResult(searchModal: SearchModal, index: number): Promise<void> {
289	    const result = searchModal.results[index];
290	    if (!result) return;
291	    if (index === searchModal.index && searchModal.previewState !== 'idle') return;
292	
293	    const generation = ++previewGeneration;
294	    const key = previewKey(result);
295	    const cached = installPreviewCache.get(key);
296	    const next: SearchModal = {
297	      ...searchModal,
298	      index,
299	      preview: cached?.contents || '',
300	      previewFile: cached?.fileName || '',
301	      previewState: cached ? 'ready' : 'loading',
302	      previewOffset: 0,
303	    };
304	    setModal(next);
305	    if (cached) return;
306	
307	    try {
308	      const preview = await loadInstallPreview(result);
309	      installPreviewCache.set(key, preview);
310	      const current = modal();
311	      if (
312	        disposed ||
313	        generation !== previewGeneration ||
314	        !current ||
315	        current.type !== 'search' ||
316	        current.phase !== 'results' ||
317	        previewKey(current.results[current.index]!) !== key
318	      ) {
319	        return;
320	      }
321	      setModal({
322	        ...current,
323	        preview: preview.contents,
324	        previewFile: preview.fileName,
325	        previewState: 'ready',
326	        previewOffset: 0,
327	      });
328	    } catch (error) {
329	      const current = modal();
330	      if (
331	        disposed ||
332	        generation !== previewGeneration ||
333	        !current ||
334	        current.type !== 'search' ||
335	        current.phase !== 'results' ||
336	        previewKey(current.results[current.index]!) !== key
337	      ) {
338	        return;
339	      }
340	      setModal({
341	        ...current,
342	        preview: (error as Error).message,
343	        previewFile: '',
344	        previewState: 'error',
345	        previewOffset: 0,
346	      });
347	    }
348	  }
349	
350	  async function submitSearch(searchModal: SearchModal): Promise<void> {
351	    if (searchModal.query.trim().length < 2) {
352	      setModal({ ...searchModal, message: 'Search needs at least two characters' });
353	      return;
354	    }
355	    const generation = ++searchGeneration;
356	    setModal({
357	      ...searchModal,
358	      loading: true,
359	      loadingMore: false,
360	      hasMore: false,
361	      message: 'Searching skills.sh',
362	    });
363	    const page = await searchSkills(searchModal.query);
364	    const current = modal();
365	    if (disposed || generation !== searchGeneration || !current || current.type !== 'search') {
366	      return;
367	    }
368	    const next: SearchModal = {
369	      ...current,
370	      phase: 'results',
371	      results: page.skills,
372	      index: 0,
373	      loading: false,
374	      loadingMore: false,
375	      hasMore: page.hasMore,
376	      message: searchStatus(page.skills.length, page.hasMore),
377	      preview: '',
378	      previewFile: '',
379	      previewState: 'idle',
380	      previewOffset: 0,
381	    };
382	    setModal(next);
383	    if (page.hasMore && shouldPrefetchSearch(next, 0)) {
384	      void loadMoreResults(next, 0);
385	    } else if (page.skills.length > 0) {
386	      void selectSearchResult(next, 0);
387	    }
388	  }
389	
390	  async function loadMoreResults(searchModal: SearchModal, selectIndex?: number): Promise<void> {
391	    if (!searchModal.hasMore || searchModal.loading || searchModal.loadingMore) return;
392	    const generation = searchGeneration;
393	    const offset = searchModal.results.length;
394	    const latest = modal();
395	    const base = latest && latest.type === 'search' ? latest : searchModal;
396	    setModal({
397	      ...base,
398	      loadingMore: true,
399	      message: searchStatus(base.results.length, true, true),
400	    });
401	    const page = await searchSkills(searchModal.query, offset);
402	    const current = modal();
403	    if (
404	      disposed ||
405	      generation !== searchGeneration ||
406	      !current ||
407	      current.type !== 'search' ||
408	      current.phase !== 'results'
409	    ) {
410	      return;
411	    }
412	    const seen = new Set(
413	      current.results.map((result) => result.slug || `${result.source}\0${result.name}`)
414	    );
415	    const extra = page.skills.filter(
416	      (result) => !seen.has(result.slug || `${result.source}\0${result.name}`)
417	    );
418	    const results = [...current.results, ...extra];
419	    const hasMore = extra.length > 0 && page.hasMore;
420	    const nextIndex =
421	      selectIndex === undefined
422	        ? Math.min(current.index, Math.max(0, results.length - 1))
423	        : Math.min(Math.max(selectIndex, 0), Math.max(0, results.length - 1));
424	    const next: SearchModal = {
425	      ...current,
426	      results,
427	      loadingMore: false,
428	      hasMore,
429	      message: searchStatus(results.length, hasMore),
430	    };
431	    setModal(next);
432	    if (hasMore && shouldPrefetchSearch(next, nextIndex)) {
433	      void loadMoreResults(next, nextIndex);
434	    } else if (results[nextIndex]) {
435	      void selectSearchResult(next, nextIndex);
436	    }
437	  }
438	
439	  function visibleSearchRows(): number {
440	    return searchResultsCapacity(dimensions().width, dimensions().height);
441	  }
442	
443	  function shouldPrefetchSearch(searchModal: SearchModal, index: number): boolean {
444	    if (!searchModal.hasMore || searchModal.loading || searchModal.loadingMore) return false;
445	    return (
446	      searchNeedsMore(index, searchModal.results.length) ||
447	      searchModal.results.length < visibleSearchRows()
448	    );
449	  }
450	
451	  function moveSearchCursor(searchModal: SearchModal, index: number): void {
452	    const next = Math.max(0, Math.min(index, searchModal.results.length - 1));
453	    void selectSearchResult(searchModal, next);
454	    if (shouldPrefetchSearch(searchModal, next)) void loadMoreResults(searchModal);
455	  }
456	
457	  function pageSearchResults(searchModal: SearchModal, direction: 1 | -1): void {
458	    const target = searchModal.index + direction * SEARCH_PAGE_SIZE;
459	    if (direction > 0 && target >= searchModal.results.length) {
460	      if (searchModal.hasMore) {
461	        void loadMoreResults(searchModal, target);
462	        return;
463	      }
464	      moveSearchCursor(searchModal, searchModal.results.length - 1);
465	      return;
466	    }
467	    moveSearchCursor(searchModal, target);
468	  }
469	
470	  async function installSelected(searchModal: SearchModal, scope: ScopeId): Promise<void> {
471	    const result = searchModal.results[searchModal.index];
472	    if (!result) {
473	      announce('No search result selected', true);
474	      return;
475	    }
476	    setBusy(true);
477	    try {
478	      const collision = await findInstallCollision(props.paths, result, scope);
479	      if (collision) {
480	        setModal({
481	          type: 'confirm',
482	          title: `Overwrite ${collision.skillName}?`,
483	          lines: [
484	            'This installed folder and its lock entry will be replaced:',
485	            '',
486	            collision.destination,
487	          ],
488	          offset: 0,
489	          action: () =>
490	            runOperation(`Installing ${result.name}`, () =>
491	              installSearchResult(props.paths, result, scope, true)
492	            ),
493	        });
494	      } else {
495	        await runOperation(`Installing ${result.name}`, () =>
496	          installSearchResult(props.paths, result, scope)
497	        );
498	      }
499	    } finally {
500	      setBusy(false);
501	    }
502	  }
503	
504	  function startUpdate(): void {
505	    const targets = actionTargets();
506	    const tracked = targets.filter((skill) => skill.tracked);
507	    if (tracked.length === 0) {
508	      announce('No tracked skill selected', true);
509	      return;
510	    }
511	    void runOperation('Updating skills. Local edits may be overwritten', () =>
512	      updateSkills(props.paths, targets)
513	    );
514	  }
515	
516	  function moveCursor(delta: number): void {
517	    const scope = activeScope();
518	    const length = scopeSkills(scope).length;
519	    if (length === 0) return;
520	    setCursor((current) => ({
521	      ...current,
522	      [scope]: Math.max(0, Math.min(current[scope] + delta, length - 1)),
523	    }));
524	  }
525	
526	  function returnToSearch(searchModal: SearchModal): void {
527	    previewGeneration++;
528	    searchGeneration++;
529	    setModal({
530	      ...searchModal,
531	      phase: 'query',
532	      results: [],
533	      index: 0,
534	      loadingMore: false,
535	      hasMore: false,
536	      preview: '',
537	      previewFile: '',
538	      previewState: 'idle',
539	      previewOffset: 0,
540	    });
541	  }
542	
543	  function handleModalKey(key: KeyEvent, activeModal: Modal): void {
544	    key.preventDefault();
545	    if (key.name === 'escape') {
546	      if (activeModal.type === 'search' && activeModal.phase === 'results') {
547	        returnToSearch(activeModal);
548	        return;
549	      }
550	      previewGeneration++;
551	      searchGeneration++;
552	      setModal(null);
553	      announce('Cancelled');
554	      return;
555	    }
556	
557	    if (activeModal.type === 'confirm') {
558	      if (key.name.toLowerCase() === 'y') void activeModal.action();
559	      if (key.name.toLowerCase() === 'n') {
560	        setModal(null);
561	        announce('Cancelled');
562	      }
563	      if (key.name === 'j' || key.name === 'down' || key.name === 'pagedown') {
564	        const step = key.name === 'pagedown' ? 8 : 1;
565	        setModal({
566	          ...activeModal,
567	          offset: Math.min(activeModal.offset + step, Math.max(0, activeModal.lines.length - 1)),
568	        });
569	      }
570	      if (key.name === 'k' || key.name === 'up' || key.name === 'pageup') {
571	        const step = key.name === 'pageup' ? 8 : 1;
572	        setModal({ ...activeModal, offset: Math.max(0, activeModal.offset - step) });
573	      }
574	      return;
575	    }
576	
577	    if (activeModal.type === 'fork') {
578	      if (isEnter(key)) return void submitFork(activeModal);
579	      if (key.name === 'backspace') {
580	        setModal({ ...activeModal, value: activeModal.value.slice(0, -1) });
581	        return;
582	      }
583	      const character = typedCharacter(key);
584	      if (character) setModal({ ...activeModal, value: activeModal.value + character });
585	      return;
586	    }
587	
588	    if (activeModal.phase === 'query') {
589	      if (isEnter(key)) return void submitSearch(activeModal);
590	      if (key.name === 'backspace') {
591	        setModal({ ...activeModal, query: activeModal.query.slice(0, -1) });
592	        return;
593	      }
594	      const character = typedCharacter(key);
595	      if (character) setModal({ ...activeModal, query: activeModal.query + character });
596	      return;
597	    }
598	
599	    if (key.name === 'backspace') {
600	      returnToSearch(activeModal);
601	    } else if (key.name === 'j' || key.name === 'down') {
602	      moveSearchCursor(activeModal, activeModal.index + 1);
603	    } else if (key.name === 'k' || key.name === 'up') {
604	      moveSearchCursor(activeModal, activeModal.index - 1);
605	    } else if (key.name.toLowerCase() === 'n') {
606	      pageSearchResults(activeModal, 1);
607	    } else if (key.name.toLowerCase() === 'p') {
608	      pageSearchResults(activeModal, -1);
609	    } else if (key.name === 'pagedown') {
610	      const max = Math.max(0, activeModal.preview.split(/\r?\n/).length - 1);
611	      setModal({
612	        ...activeModal,
613	        previewOffset: Math.min(max, activeModal.previewOffset + 10),
614	      });
615	    } else if (key.name === 'pageup') {
616	      setModal({ ...activeModal, previewOffset: Math.max(0, activeModal.previewOffset - 10) });
617	    } else if (isEnter(key)) {
618	      void installSelected(activeModal, activeModal.scope);
619	    } else if (key.name.toLowerCase() === 'i') {
620	      void installSelected(activeModal, key.shift ? 'global' : 'project');
621	    }
622	  }
623	
624	  useKeyboard((key) => {
625	    const activeModal = modal();
626	    if (activeModal) return handleModalKey(key, activeModal);
627	    if (busy()) return;
628	    const keyName = key.name.toLowerCase();
629	
630	    if ((key.ctrl && keyName === 'c') || keyName === 'q') return renderer.destroy();
631	    if (keyName === 'j' || keyName === 'down') return moveCursor(1);
632	    if (keyName === 'k' || keyName === 'up') return moveCursor(-1);
633	    if (keyName === 'h' || keyName === 'left') {
634	      setActiveScope('project');
635	      return;
636	    }
637	    if (keyName === 'l' || keyName === 'right') {
638	      setActiveScope('global');
639	      return;
640	    }
641	    if (keyName === 'x') {
642	      const skill = currentSkill();
643	      if (!skill) return;
644	      setSelected((previous) => {
645	        const next = new Set(previous);
646	        if (next.has(skill.id)) next.delete(skill.id);
647	        else next.add(skill.id);
648	        return next;
649	      });
650	      return;
651	    }
652	    if (keyName === 'd' && key.shift) return openDelete();
653	    if (keyName === 'm' && key.shift) return void startMove();
654	    if (keyName === 'f' && key.shift) return openFork();
655	    if (keyName === 'u' && key.shift) return startUpdate();
656	    if (keyName === 'i') return openSearch(key.shift ? 'global' : 'project');
657	    if (keyName === 'r') return void refresh(true);
658	  });
659	
660	  onMount(() => void refresh(true));
661	  onCleanup(() => {
662	    disposed = true;
663	    checkGeneration++;
664	    previewGeneration++;
665	    searchGeneration++;
666	  });
667	
668	  const paneBudget = () => Math.max(3, dimensions().height - 10);
669	
670	  function paneRows(scope: ScopeId): SkillRecord[] {
671	    const list = scopeSkills(scope);
672	    const budget = paneBudget();
673	    const center = cursor()[scope];
674	    const start = Math.max(0, Math.min(center - Math.floor(budget / 2), list.length - budget));
675	    return list.slice(start, start + budget);
676	  }
677	
678	  function paneTitle(scope: ScopeId): string {
679	    const data = scopeSnapshot(scope);
680	    const count = data?.skills.length || 0;
681	    const hidden = data?.hiddenLockEntries || 0;
682	    const parts = [`${scope === 'project' ? 'Project' : 'Global'} ${count}`];
683	    if (count > paneBudget()) parts.push(`${cursor()[scope] + 1}/${count}`);
684	    if (hidden) parts.push(`${hidden} hidden`);
685	    return parts.join(' · ');
686	  }
