688	  const modalTitle = createMemo(() => {
689	    const active = modal();
690	    if (!active) return '';
691	    if (active.type === 'search') {
692	      return `Install in ${active.scope} scope`;
693	    }
694	    if (active.type === 'fork') return `Fork ${active.skill.folderName}`;
695	    return active.title;
696	  });
