699	    const active = modal();
700	    if (!active) return null;
701	    if (active.type === 'confirm') return <ConfirmView modal={active} />;
702	    if (active.type === 'fork') return <ForkView modal={active} />;
703	    return active.phase === 'query' ? (
704	      <SearchQueryView modal={active} />
705	    ) : (
706	      <SearchResultsView modal={active} />
707	    );
708	  };
709	
710	  return (
711	    <box width="100%" height="100%" flexDirection="column" backgroundColor={COLORS.bg} padding={1}>
712	      <box height={2} flexDirection="row" justifyContent="space-between">
713	        <text>
714	          <span style={{ fg: COLORS.active, bold: true }}>skillsui</span>
715	        </text>
716	        <text fg={COLORS.dim} truncate={true}>
717	          {shortenHome(props.paths.projectRoot)}
718	        </text>
719	      </box>
