728	              rows={paneRows(scope)}
729	              empty={scopeSkills(scope).length === 0}
730	              cursorId={currentSkill()?.id ?? null}
731	              selected={(id) => selected().has(id)}
732	              updateState={(id) => updates()[id]}
733	            />
