1	/** @jsxImportSource @opentui/solid */
2	
3	import { For, Show, type JSX } from 'solid-js';
4	import { useTerminalDimensions } from '@opentui/solid';
5	import type { ScopeId, SkillRecord } from '../types.ts';
6	import type { SearchSkill } from '../install.ts';
7	import { COLORS, HintLine, fit, formatInstalls } from './common.tsx';
8	
9	export interface ConfirmModal {
10	  type: 'confirm';
11	  title: string;
12	  lines: string[];
13	  offset: number;
14	  action: () => Promise<void>;
15	}
16	
17	export interface ForkModal {
18	  type: 'fork';
19	  skill: SkillRecord;
20	  value: string;
21	}
22	
23	export interface SearchModal {
24	  type: 'search';
25	  scope: ScopeId;
26	  phase: 'query' | 'results';
27	  query: string;
28	  results: SearchSkill[];
29	  index: number;
30	  loading: boolean;
31	  loadingMore: boolean;
32	  hasMore: boolean;
33	  message: string;
34	  preview: string;
35	  previewFile: string;
36	  previewState: 'idle' | 'loading' | 'ready' | 'error';
37	  previewOffset: number;
38	}
39	
40	export type Modal = ConfirmModal | ForkModal | SearchModal;
41	
42	export function modalGeometry(
43	  terminalWidth: number,
44	  terminalHeight: number
45	): { left: number; top: number; width: number; height: number } {
46	  // Integer rows and columns: fractional percentage layout rounds pane heights
47	  // up while flooring child offsets, which makes footers overlap pane borders.
48	  const width = Math.max(40, Math.floor(terminalWidth * 0.8));
49	  const height = Math.max(10, Math.floor(terminalHeight * 0.7));
50	  return {
51	    left: Math.max(0, Math.floor((terminalWidth - width) / 2)),
52	    top: Math.max(1, Math.floor((terminalHeight - height) / 2)),
53	    width,
54	    height,
55	  };
56	}
57	
58	export function ModalFrame(props: { title: string; danger: boolean; children: JSX.Element }) {
59	  const dimensions = useTerminalDimensions();
60	  const geometry = () => modalGeometry(dimensions().width, dimensions().height);
61	  return (
62	    <>
63	      <box
64	        position="absolute"
65	        left={0}
66	        top={0}
67	        width="100%"
68	        height="100%"
69	        zIndex={10}
70	        backgroundColor={COLORS.backdrop}
71	      />
72	      <box
73	        position="absolute"
74	        left={geometry().left}
75	        top={geometry().top}
76	        width={geometry().width}
77	        height={geometry().height}
78	        zIndex={20}
79	        flexDirection="column"
80	        border={true}
81	        borderStyle="double"
82	        borderColor={props.danger ? COLORS.danger : COLORS.active}
83	        backgroundColor="#0c0e13"
84	        title={props.title}
85	        titleColor={props.danger ? COLORS.danger : COLORS.active}
86	        padding={1}
87	        overflow="hidden"
88	      >
89	        {props.children}
90	      </box>
91	    </>
92	  );
93	}
94	
95	/** Visible search-result rows after the modal chrome and the status line. */
96	export function searchResultsCapacity(terminalWidth: number, terminalHeight: number): number {
97	  return Math.max(4, modalGeometry(terminalWidth, terminalHeight).height - 10);
98	}
99	
100	/** Inner height of a modal after the frame's border and padding. */
101	function useModalBodyHeight(): () => number {
102	  const dimensions = useTerminalDimensions();
103	  return () => modalGeometry(dimensions().width, dimensions().height).height - 4;
104	}
105	
106	export function ConfirmView(props: { modal: ConfirmModal }) {
107	  const bodyHeight = useModalBodyHeight();
108	  const capacity = () => Math.max(3, bodyHeight() - 5);
109	  const rows = () =>
110	    props.modal.lines
111	      .slice(props.modal.offset, props.modal.offset + capacity())
112	      .map((line, offset) => ({ index: props.modal.offset + offset, line }));
113	  const remaining = () => props.modal.lines.length - props.modal.offset - capacity();
114	
115	  return (
116	    <>
117	      <box flexGrow={1} minHeight={0} flexDirection="column" overflow="hidden">
118	        <Show when={props.modal.offset > 0}>
119	          <text height={1} fg={COLORS.dim}>{`↑ ${props.modal.offset} more`}</text>
120	        </Show>
121	        <For each={rows()}>
122	          {(row) => (
123	            <text height={1} fg={row.index === 0 ? COLORS.dim : COLORS.text}>
124	              {row.line}
125	            </text>
126	          )}
127	        </For>
128	        <Show when={remaining() > 0}>
129	          <text height={1} fg={COLORS.dim}>{`↓ ${remaining()} more`}</text>
130	        </Show>
131	      </box>
132	      <HintLine
133	        hints={[
134	          ['y', 'confirm'],
135	          ['n', 'cancel'],
136	          ['j/k', 'scroll'],
137	        ]}
138	      />
139	    </>
140	  );
141	}
142	
143	export function ForkView(props: { modal: ForkModal }) {
144	  return (
145	    <>
146	      <box flexGrow={1} flexDirection="column">
147	        <text fg={COLORS.dim}>The source remains tracked. The new copy is local.</text>
148	        <box height={1} />
149	        <text>
150	          <span style={{ fg: COLORS.dim }}>{'Name: '}</span>
151	          <span style={{ fg: COLORS.text }}>{props.modal.value}</span>
152	          <span style={{ fg: COLORS.active }}>_</span>
153	        </text>
154	      </box>
155	      <HintLine
156	        hints={[
157	          ['Enter', 'fork'],
158	          ['Esc', 'cancel'],
159	        ]}
160	      />
161	    </>
162	  );
163	}
164	
165	export function SearchQueryView(props: { modal: SearchModal }) {
166	  return (
167	    <>
168	      <box flexGrow={1} flexDirection="column">
169	        <text>
170	          <span style={{ fg: COLORS.dim }}>{'Search: '}</span>
171	          <span style={{ fg: COLORS.text }}>{props.modal.query}</span>
172	          <span style={{ fg: COLORS.active }}>_</span>
173	        </text>
174	        <box height={1} />
175	        <text fg={COLORS.dim} truncate={true}>
176	          {props.modal.message}
177	        </text>
178	      </box>
179	      <HintLine
180	        hints={[
181	          ['Enter', 'search'],
182	          ['Backspace', 'delete'],
183	          ['Esc', 'close'],
184	        ]}
185	      />
186	    </>
187	  );
188	}
189	
190	export function SearchResultsView(props: { modal: SearchModal }) {
191	  const dimensions = useTerminalDimensions();
192	  const bodyHeight = useModalBodyHeight();
193	  const capacity = () => Math.max(4, bodyHeight() - 6);
194	  const previewCapacity = () => Math.max(3, bodyHeight() - 6);
195	
196	  // Integer copy of the flex layout so names and sources ellipsize cleanly
197	  // instead of colliding with each other mid-row.
198	  const resultsPaneWidth = () => {
199	    const inner = modalGeometry(dimensions().width, dimensions().height).width - 4;
200	    return Math.floor(inner * 0.45) - 5;
201	  };
202	
203	  const rows = () => {
204	    const size = capacity();
205	    const start = Math.max(
206	      0,
207	      Math.min(props.modal.index - Math.floor(size / 2), props.modal.results.length - size)
208	    );
209	    return props.modal.results
210	      .slice(start, start + size)
211	      .map((result, offset) => ({ index: start + offset, result }));
212	  };
213	
214	  const selectedResult = () => props.modal.results[props.modal.index];
215	
216	  const visiblePreview = () =>
217	    props.modal.preview
218	      .split(/\r?\n/)
219	      .slice(props.modal.previewOffset, props.modal.previewOffset + previewCapacity())
220	      .join('\n');
221	
222	  const resultsTitle = () => {
223	    if (props.modal.results.length <= capacity()) return 'Results';
224	    return `Results ${props.modal.index + 1}/${props.modal.results.length}`;
225	  };
226	
227	  const previewTitle = () => {
228	    const result = selectedResult();
229	    if (!result) return 'Preview';
230	    const label = `Preview ${result.name}`;
231	    const total = props.modal.preview ? props.modal.preview.split(/\r?\n/).length : 0;
232	    if (total <= previewCapacity()) return label;
233	    const end = Math.min(props.modal.previewOffset + previewCapacity(), total);
234	    return `${label} · ${props.modal.previewOffset + 1}-${end}/${total}`;
235	  };
236	
237	  return (
238	    <>
239	      <box flexGrow={1} minHeight={0} flexDirection="row" gap={1} overflow="hidden">
240	        <box
241	          width="45%"
242	          flexDirection="column"
243	          border={true}
244	          borderStyle="rounded"
245	          borderColor={COLORS.border}
246	          title={resultsTitle()}
247	          titleColor={COLORS.dim}
248	          paddingX={1}
249	          overflow="hidden"
250	        >
251	          <text fg={COLORS.dim} height={1} truncate={true}>
252	            {props.modal.message}
253	          </text>
254	          <For each={rows()}>
255	            {(row) => {
256	              const current = () => row.index === props.modal.index;
257	              // Names get priority; the source stays only when it leaves at
258	              // least a readable stub, otherwise just the install count shows.
259	              const segments = () => {
260	                const width = resultsPaneWidth();
261	                const installs = formatInstalls(row.result.installs);
262	                let nameWidth = Math.min(row.result.name.length, Math.ceil(width * 0.55));
263	                let sourceWidth = width - nameWidth - installs.length - 6;
264	                if (sourceWidth < 8) {
265	                  sourceWidth = 0;
266	                  nameWidth = Math.min(row.result.name.length, width - installs.length - 4);
267	                }
268	                return {
269	                  name: fit(row.result.name, nameWidth),
270	                  source: sourceWidth ? fit(row.result.source, sourceWidth) : '',
271	                  installs,
272	                };
273	              };
274	              return (
275	                <box
276	                  height={1}
277	                  width="100%"
278	                  flexDirection="row"
279	                  backgroundColor={current() ? COLORS.cursor : undefined}
280	                >
281	                  <text flexGrow={1} truncate={true}>
282	                    <span style={{ fg: current() ? COLORS.accent : COLORS.dim }}>
283	                      {current() ? '❯ ' : '  '}
284	                    </span>
285	                    {current() ? (
286	                      <b style={{ fg: COLORS.text }}>{segments().name}</b>
287	                    ) : (
288	                      <span style={{ fg: COLORS.text }}>{segments().name}</span>
289	                    )}
290	                  </text>
291	                  <text flexShrink={0}>
292	                    {segments().source ? (
293	                      <span style={{ fg: COLORS.dim }}>{`${segments().source} · `}</span>
294	                    ) : null}
295	                    <span style={{ fg: COLORS.text }}>{segments().installs}</span>
296	                  </text>
297	                </box>
298	              );
299	            }}
300	          </For>
301	        </box>
302	
303	        <box
304	          width="55%"
305	          flexDirection="column"
306	          border={true}
307	          borderStyle="rounded"
308	          borderColor={COLORS.border}
309	          title={previewTitle()}
310	          titleColor={COLORS.accent}
311	          paddingX={1}
312	          overflow="hidden"
313	        >
314	          <Show when={selectedResult()} fallback={<text fg={COLORS.dim}>No skill selected</text>}>
315	            <text height={1} truncate={true}>
316	              {props.modal.previewFile ? (
317	                <>
318	                  <span style={{ fg: COLORS.accent }}>{props.modal.previewFile}</span>
319	                  <span style={{ fg: COLORS.dim }}>{` · ${selectedResult()!.source}`}</span>
320	                </>
321	              ) : (
322	                <span style={{ fg: COLORS.dim }}>{selectedResult()!.source}</span>
323	              )}
324	            </text>
325	            <Show
326	              when={props.modal.previewState !== 'loading'}
327	              fallback={<text fg={COLORS.dim}>Loading preview…</text>}
328	            >
329	              <text
330	                fg={props.modal.previewState === 'error' ? COLORS.warning : COLORS.text}
331	                wrapMode="word"
332	                flexGrow={1}
333	              >
334	                {visiblePreview()}
335	              </text>
336	            </Show>
337	          </Show>
338	        </box>
339	      </box>
340	      <HintLine
341	        hints={[
342	          ['j/k', 'move'],
343	          ['n/p', 'page'],
344	          ['Enter', 'install'],
345	          ['i', 'project'],
346	          ['I', 'global'],
347	          ['PageUp/PageDown', 'preview'],
348	          ['Esc', 'search'],
349	        ]}
350	      />
351	    </>
352	  );
353	}
